const fs = require('node:fs');
const fastGlob = require('fast-glob');

const { globSync } = fastGlob;
const files = globSync('app/lib/**/*.{ts,tsx}');
let changedCount = 0;

for (const file of files) {
  let content = fs.readFileSync(file, 'utf8');
  let original = content;

  // Fix syntax errors generated by earlier regex
  content = content.replace(/CoreMessage\s+as\s+Message\s+as\s+Message/g, 'CoreMessage as Message');
  content = content.replace(/UIMessage\s+as\s+Message\s+as\s+Message/g, 'UIMessage as Message');

  // Fix general "as Message as Message" if it exists without Core/UI prefix
  content = content.replace(/Message\s+as\s+Message\s+as\s+Message/g, 'Message');
  content = content.replace(/Message\s+as\s+Message/g, 'Message');

  if (content !== original) {
    fs.writeFileSync(file, content);
    changedCount++;
  }
}

console.log('Changed', changedCount, 'files');
